      "claims": ["c3", "c4"]
    }
  ],
  "terms_defined": [
    {
      "term": "лигнит",
      "term_en": "lignite",
      "abbr": "",
      "definition": "Вид угля, стоящий рядом с торфом. В тексте упомянут как слой на поверхности верхней части дельтовой равнины. Общее определение дано не по главе.",
      "claims": ["c3"]
    },
    {
      "term": "гумидный климат",
      "term_en": "humid climate",
      "abbr": "",
      "definition": "Влажный климат. В тексте это условие, при котором накапливаются слои лигнита или торфа на верхней части равнины.",
      "claims": ["c4"]
    },
    {
      "term": "маркирующий горизонт",
      "term_en": "marker horizon",
      "abbr": "",
      "definition": "Слой, легко узнаваемый и прослеживаемый на многих разрезах. По нему сопоставляют разрезы разных скважин.",
      "claims": ["c3"]
    }
